def every_account_becomes_a_person(apps, schema_editor):
    """structure.md §2: each account gets a person, with its name, and its address
    marked verified, as an operator typed it in and it's been used to log in. Nothing in
    accounts changes, so every sub, which is the account's id, stays the same."""
    User = apps.get_model("accounts", "User")
    Person = apps.get_model("structure", "Person")
    EmailAddress = apps.get_model("structure", "EmailAddress")
    now = django.utils.timezone.now()
    for user in User.objects.order_by("pk").iterator():
        person = Person.objects.create(name=user.name, user=user, created_at=user.date_joined)
        EmailAddress.objects.create(person=person, address=user.email.strip().lower(), verified_at=now)


